// --- reading a Streamable HTTP MCP reply ------------------------------------
// The transport answers `event: message\ndata: {...}` even for a one-shot call,
// so the JSON-RPC envelope has to be lifted out of the SSE frame before
// anything can be read from it.
function unwrap(text) {
  const body = String(text === null || text === undefined ? '' : text);
  for (const line of body.split('\n')) {
    if (line.startsWith('data:')) {
      try { return JSON.parse(line.slice(5).trim()); } catch (e) { return null; }
    }
  }
  try { return JSON.parse(body); } catch (e) { return null; }
}

// Three ways a call can come back without data, and only one of them is an
// error: a transport failure, a tool error (HTTP 200 with `isError` on the
// envelope), and a tool that simply has nothing to say and answers in prose
// despite response_format "json". The third one throws JSON.parse on a
// perfectly healthy response.
function payloadOf(item) {
  const raw = item && item.json ? (item.json.mcp !== undefined ? item.json.mcp : item.json.data) : '';
  const env = unwrap(raw);
  if (!env) return { error: 'no JSON-RPC envelope came back from the server' };
  if (env.error) return { error: String((env.error && env.error.message) || 'JSON-RPC error') };
  const result = env.result || {};
  const text = String((((result.content || [])[0]) || {}).text || '');
  if (result.isError) return { error: text.slice(0, 200) };
  try { return { data: JSON.parse(toStrictJson(text)) }; } catch (e) { return { note: text.slice(0, 200) }; }
}

// The server serialises with Python's json.dumps, which writes a bare NaN for a
// missing float. get_analyst_estimates carries one on most tickers: the LTG row
// of growthEstimates comes back `"stockTrend": NaN`. Bare NaN and Infinity are
// valid Python output and neither is valid JSON, so JSON.parse throws on a
// payload that is otherwise perfect - and every EPS field arrives null on a run
// where the call succeeded and no node went red. Only value positions are
// rewritten, so a string that happens to read "NaN" is left alone.
function toStrictJson(text) {
  return String(text).replace(/:\s*(-?Infinity|NaN)(\s*[,}\]])/g, ': null$2');
}

// Yahoo's gaps arrive as the string "N/A", never as null. Number('N/A') is NaN
// and Number('') is 0, and either one reaching a comparison makes a drift check
// quietly wrong rather than loudly broken.
function num(value) {
  if (value === null || value === undefined || value === '' || value === 'N/A') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

// The endpoint answering at all is not proof it is an MCP server, and an MCP
// server answering is not proof it is this one. tools/list is the cheapest call
// in the protocol, so a wrong URL or an old build surfaces here rather than as
// an empty digest five nodes later.
const url = $('Settings').first().json.mcp_url;
const NEEDED = [
  'get_analyst_recommendations',
  'get_analyst_estimates',
  'get_stock_quote',
  'get_market_news',
];

const env = unwrap($json.mcp !== undefined ? $json.mcp : $json.data);
const tools = env && env.result && Array.isArray(env.result.tools) ? env.result.tools : null;

if (!tools) {
  throw new Error(
    'No tool list came back from ' + url + '. A Streamable HTTP MCP server ' +
    'answers POST on /mcp: a 404 usually means the path is missing /mcp, and a ' +
    '421 means the server is up but your Host header is not on its allow-list ' +
    '(start it with --allowed-host). From n8n in Docker the host machine is ' +
    'host.docker.internal, not localhost.'
  );
}

const have = new Set(tools.map((t) => String(t.name)));
const missing = NEEDED.filter((t) => !have.has(t));
if (missing.length) {
  throw new Error(
    'The server at ' + url + ' is missing ' + missing.join(', ') + '. It ' +
    'offers ' + tools.length + ' tool(s), so it is an MCP server - just not ' +
    'this one. Expected yahoo-finance-mcp-server 1.3.0 or later.'
  );
}

return [{ json: { mcp_url: url, tools_offered: tools.length, tools_needed: NEEDED } }];

// One item per ticker, so each of the three calls below runs once per ticker
// and the three lanes stay index-aligned all the way to the merge.
const cfg = $('Settings').first().json;

const tickers = String(cfg.tickers || '')
  .split(',')
  .map((t) => t.trim().toUpperCase())
  // A ticker is letters, digits, dot and dash. Anything else is a typo, and it
  // would be interpolated straight into the JSON-RPC body below.
  .filter((t) => /^[A-Z0-9.\-]{1,10}$/.test(t))
  .slice(0, Math.max(1, Number(cfg.max_tickers) || 12));

if (!tickers.length) {
  throw new Error(
    'No usable tickers in Settings. Expected a comma separated list like ' +
    '"AAPL, MSFT, NVDA".'
  );
}

// Deduplicated, because the Data Table is keyed on the ticker and the same
// symbol listed twice would race itself on the upsert.
return [...new Set(tickers)].map((ticker) => ({ json: { ticker } }));

