// get_analyst_estimates is here for the EPS side. The mean price target comes
// from the ratings call, which returns it alongside the consensus and the live
// price - asking this tool for it as well would be a second answer to the same
// question, and the two disagree about the key name anyway: `current` here,
// `currentPrice` there.
const asked = $('Pick The Watchlist').all().map((i) => i.json.ticker);
const items = $input.all();

return asked.map((ticker, i) => {
  const got = payloadOf(items[i]);
  const d = got.data || {};
  const eps = Array.isArray(d.earningsEstimate) ? d.earningsEstimate : [];
  const period = (p) => eps.find((e) => String(e.period) === p) || {};

  return {
    json: {
      ticker,
      eps_this_year: num(period('0y').avg),
      eps_next_year: num(period('+1y').avg),
      eps_next_year_analysts: num(period('+1y').numberOfAnalysts),
      // Yahoo's own year-on-year growth figure, already a fraction. Kept as
      // context for the brief, never as a trigger - it moves with the calendar
      // as much as with the estimates.
      eps_growth_next_year: num(period('+1y').growth),
      // A note here means the call succeeded and its text would not parse.
      // Left as null it produced four null EPS fields on a green run, which
      // is the quietest possible way for a lane to stop working.
      estimates_error: got.error || got.note || null,
    },
  };
});

