// spread, the consensus, three or four months of rating distribution, and the
// individual firm actions. All four are read here; only the first two are
// compared against stored history, because the other two arrive with their own.
const cfg = $('Settings').first().json;
const asked = $('Pick The Watchlist').all().map((i) => i.json.ticker);
const items = $input.all();

const windowDays = Math.max(1, Number(cfg.action_days) || 7);
const cutoff = new Date(Date.now() - windowDays * 86400000).toISOString().slice(0, 10);

// recommendationKey is Yahoo's own vocabulary, not a model's, so this maps five
// known values and records anything else as unknown rather than passing it
// through - an unrecognised string would read as a rating change next week.
const RATINGS = new Set(['strong_buy', 'buy', 'hold', 'sell', 'strong_sell']);
function rating(value) {
  const k = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  if (!k || k === 'n/a' || k === 'none') return null;
  return RATINGS.has(k) ? k : 'unknown';
}

function bullShare(row) {
  if (!row) return null;
  const total = ['strongBuy', 'buy', 'hold', 'sell', 'strongSell']
    .reduce((sum, k) => sum + (num(row[k]) || 0), 0);
  if (!total) return null;
  return ((num(row.strongBuy) || 0) + (num(row.buy) || 0)) / total;
}

return asked.map((ticker, i) => {
  const got = payloadOf(items[i]);
  const d = got.data || {};
  const targets = d.priceTargets || {};
  const consensus = d.consensus || {};
  const trend = Array.isArray(d.recommendationTrend) ? d.recommendationTrend : [];
  const at = (p) => trend.find((r) => String(r.period) === p) || null;

  // Capped at ten rows by the API, not by a date - for a heavily covered name
  // those ten spanned 16 days, for a thinly covered one ten months. So an empty
  // window here means "nothing in the last ten actions", which is not the same
  // sentence as "nothing happened", and the brief says it that way.
  const actions = (Array.isArray(d.upgradesDowngrades) ? d.upgradesDowngrades : [])
    .map((a) => {
      const prior = num(a.priorPriceTarget);
      const now = num(a.currentPriceTarget);
      const from = String(a.FromGrade || '').trim();
      const to = String(a.ToGrade || '').trim();
      // An initiation arrives with priorPriceTarget 0 and an empty FromGrade.
      // A percentage change from zero is Infinity, which formats as
      // "Infinity%" in a message that is supposed to read like a sentence.
      const initiation = !from || prior === null || prior === 0;
      return {
        when: String(a.GradeDate || '').slice(0, 10),
        firm: String(a.Firm || '').slice(0, 60),
        from_grade: from,
        to_grade: to,
        prior_target: prior,
        new_target: now,
        target_change_pct:
          initiation || now === null || prior === null
            ? null
            : Number((((now - prior) / prior) * 100).toFixed(1)),
        initiation,
        graded: Boolean(from && to && from.toLowerCase() !== to.toLowerCase()),
      };
    })
    .filter((a) => a.when && a.when >= cutoff)
    .filter((a) => a.graded || a.initiation || (a.target_change_pct !== null && Math.abs(a.target_change_pct) >= 0.5));

  const now = bullShare(at('0m'));
  const before = bullShare(at('-1m'));

  return {
    json: {
      ticker,
      mean_target: num(targets.mean),
      high_target: num(targets.high),
      low_target: num(targets.low),
      // The ratings tool calls the live price currentPrice; the estimates tool
      // calls the same number current. Neither is wrong and neither is shared.
      price_from_ratings: num(targets.currentPrice),
      consensus: rating(consensus.recommendationKey),
      analyst_count: num(consensus.numberOfAnalysts),
      bull_share: now === null ? null : Number((now * 100).toFixed(1)),
      bull_share_prev: before === null ? null : Number((before * 100).toFixed(1)),
      firm_actions: actions,
      action_window_days: windowDays,
      ratings_error: got.error || got.note || null,
    },
  };
});

