// The quote is here for two reasons that have nothing to do with the price
// itself. longName is what makes the news filter below able to tell an Nvidia
// story from a copper story, and the day's move is the context that decides
// whether a cut target is news: a target cut on a flat tape is an analyst
// changing their mind, a target cut on a 9% drawdown is an analyst catching up.
const asked = $('Pick The Watchlist').all().map((i) => i.json.ticker);
const items = $input.all();

return asked.map((ticker, i) => {
  const got = payloadOf(items[i]);
  const d = got.data || {};
  const name = String(d.longName || '').trim();

  // An unknown symbol is not an error on this API: it returns 200, isError
  // false, and every field set to the string "N/A". Without this check it
  // would travel all the way to the digest as a ticker with no numbers.
  const found = Boolean(name) && name !== 'N/A';

  return {
    json: {
      ticker,
      long_name: found ? name : null,
      price: num(d.currentPrice),
      change_pct: num(d.changePercent),
      sector: d.sector === 'N/A' ? null : String(d.sector || '') || null,
      found,
      quote_error: got.error || got.note || null,
    },
  };
});

// The three lanes are read by name rather than off the merge, which is here to
// make the branch wait for all of them. Each lane already emits one item per
// ticker in watchlist order, so they join on the ticker itself.
const cfg = $('Settings').first().json;
const targetDrift = Math.abs(Number(cfg.target_move_pct) || 5);
const epsDrift = Math.abs(Number(cfg.eps_move_pct) || 3);
const today = new Date().toISOString().slice(0, 10);

const byTicker = (nodeName) => {
  const map = {};
  for (const item of $(nodeName).all()) {
    const t = String(item.json.ticker || '').toUpperCase();
    if (t) map[t] = item.json;
  }
  return map;
};

const targets = byTicker('Read The Price Targets');
const ratings = byTicker('Read The Ratings');
const quotes = byTicker('Read The Price');

// The table holds one row per ticker. Newest wins if an interrupted run ever
// left a duplicate behind.
const history = {};
for (const item of $('Read What We Saw Last Time').all()) {
  const r = item.json || {};
  const t = String(r.ticker || '').toUpperCase();
  if (!t) continue;
  const seen = String(r.seen_on || '');
  if (!history[t] || seen > String(history[t].seen_on || '')) history[t] = r;
}

const pct = (now, was) =>
  now === null || was === null || !was ? null : Number((((now - was) / was) * 100).toFixed(2));

const rows = [];
const notFound = [];
const failed = [];

for (const item of $('Pick The Watchlist').all()) {
  const ticker = String(item.json.ticker || '').toUpperCase();
  const q = quotes[ticker] || {};
  const r = ratings[ticker] || {};
  const e = targets[ticker] || {};

  // Only two of the three lanes are load bearing. The quote carries the name
  // and the price, the ratings call carries the target and the consensus, and
  // without either there is nothing to report. The estimates call only carries
  // EPS, so losing it costs one of the three signals rather than the ticker.
  const problem = r.ratings_error || q.quote_error;
  if (problem) {
    failed.push(ticker + ' (' + String(problem).slice(0, 80) + ')');
    continue;
  }
  if (!q.found) {
    notFound.push(ticker);
    continue;
  }

  const prev = history[ticker] || {};
  const firstRun = !prev.ticker;

  const meanTarget = r.mean_target === undefined ? null : r.mean_target;
  const epsNext = e.eps_next_year === undefined ? null : e.eps_next_year;
  const prevTarget = prev.mean_target === undefined ? null : Number(prev.mean_target);
  const prevEps = prev.eps_next_year === undefined ? null : Number(prev.eps_next_year);
  const prevConsensus = String(prev.consensus || '') || null;

  const targetMove = pct(meanTarget, Number.isFinite(prevTarget) ? prevTarget : null);
  const epsMove = pct(epsNext, Number.isFinite(prevEps) ? prevEps : null);

  const ratingChanged =
    Boolean(prevConsensus) &&
    Boolean(r.consensus) &&
    r.consensus !== 'unknown' &&
    prevConsensus !== 'unknown' &&
    r.consensus !== prevConsensus;

  const actions = Array.isArray(r.firm_actions) ? r.firm_actions : [];

  // Four independent reasons to speak. The firm actions come with their own
  // history, so they fire on the first run too; the three stored numbers
  // cannot, because a baseline is not a change.
  const moved =
    actions.length > 0 ||
    (!firstRun &&
      ((targetMove !== null && Math.abs(targetMove) >= targetDrift) ||
        (epsMove !== null && Math.abs(epsMove) >= epsDrift) ||
        ratingChanged));

  const price = q.price !== null && q.price !== undefined ? q.price : r.price_from_ratings;

  rows.push({
    json: {
      ticker,
      long_name: q.long_name,
      seen_on: today,
      usable: true,
      price,
      change_pct: q.change_pct,
      mean_target: meanTarget,
      high_target: r.high_target,
      low_target: r.low_target,
      prev_target: Number.isFinite(prevTarget) ? prevTarget : null,
      target_move_pct: targetMove,
      consensus: r.consensus || 'unknown',
      prev_consensus: prevConsensus,
      rating_changed: ratingChanged,
      analyst_count: r.analyst_count,
      bull_share: r.bull_share,
      bull_share_prev: r.bull_share_prev,
      eps_next_year: epsNext,
      prev_eps_next_year: Number.isFinite(prevEps) ? prevEps : null,
      eps_move_pct: epsMove,
      eps_growth_next_year: e.eps_growth_next_year,
      eps_note: e.estimates_error || null,
      firm_actions: actions,
      action_window_days: r.action_window_days,
      upside_pct:
        price !== null && price !== undefined && meanTarget !== null
          ? Number((((meanTarget - price) / price) * 100).toFixed(2))
          : null,
      first_run: firstRun,
      moved,
      not_found: notFound,
      failed,
    },
  });
}

// Never return zero items. A branch that ended here would take neither the
// quiet path nor the loud one, the table would stop being written, and the
// workflow would go silent with every node green.
if (!rows.length) {
  return [{
    json: {
      ticker: '',
      seen_on: today,
      usable: false,
      moved: false,
      first_run: false,
      firm_actions: [],
      not_found: notFound,
      failed,
      empty_run: true,
    },
  }];
}

return rows;

