}

// Three ways a call can come back without data, and only one of them is an
// error: a transport failure, a tool error (HTTP 200 with `isError` on the
// envelope), and a tool that simply has nothing to say and answers in prose
// despite response_format "json". The third one throws JSON.parse on a
// perfectly healthy response.
function payloadOf(item) {
  const raw = item && item.json ? (item.json.mcp !== undefined ? item.json.mcp : item.json.data) : '';
  const env = unwrap(raw);
  if (!env) return { error: 'no JSON-RPC envelope came back from the server' };
  if (env.error) return { error: String((env.error && env.error.message) || 'JSON-RPC error') };
  const result = env.result || {};
  const text = String((((result.content || [])[0]) || {}).text || '');
  if (result.isError) return { error: text.slice(0, 200) };
  try { return { data: JSON.parse(toStrictJson(text)) }; } catch (e) { return { note: text.slice(0, 200) }; }
}

// The server serialises with Python's json.dumps, which writes a bare NaN for a
// missing float. get_analyst_estimates carries one on most tickers: the LTG row
// of growthEstimates comes back `"stockTrend": NaN`. Bare NaN and Infinity are
// valid Python output and neither is valid JSON, so JSON.parse throws on a
// payload that is otherwise perfect - and every EPS field arrives null on a run
// where the call succeeded and no node went red. Only value positions are
// rewritten, so a string that happens to read "NaN" is left alone.
function toStrictJson(text) {
  return String(text).replace(/:\s*(-?Infinity|NaN)(\s*[,}\]])/g, ': null$2');
}

// Yahoo's gaps arrive as the string "N/A", never as null. Number('N/A') is NaN
// and Number('') is 0, and either one reaching a comparison makes a drift check
// quietly wrong rather than loudly broken.
function num(value) {
  if (value === null || value === undefined || value === '' || value === 'N/A') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

// Yahoo's feed for a ticker is only loosely about that ticker. Ten stories
// returned for NVDA on 2026-09-06 included two about Nvidia and the rest about
// copper, Pepsi and Visa; AAPL, SOFI and PLTR came back 8-9 out of 10 on topic.
// Handing the unfiltered feed to a model asking why a price target moved is how
// a copper rally ends up explaining a semiconductor downgrade.
const movers = $('Compare With Last Time').all()
  .map((i) => i.json)
  .filter((r) => r.moved && r.ticker);
const items = $input.all();

// "Apple Inc." -> "apple". The suffix is what every listed company shares and
// nothing a headline uses.
function nameKey(longName) {
  return String(longName || '')
    .replace(/\b(inc|corp|corporation|company|co|ltd|limited|plc|holdings|group|technologies|the)\b/gi, ' ')
    .replace(/[^A-Za-z0-9 ]+/g, ' ')
    .trim()
    .split(/\s+/)[0] || '';
}

return movers.map((row, i) => {
  const got = payloadOf(items[i]);
  const ticker = row.ticker;
  const key = nameKey(row.long_name);
  // The prose case: a successful call whose text is "No recent news found for
  // ZZZZ." rather than JSON. payloadOf reports it as a note, not an error.
  const news = got.data && Array.isArray(got.data.news) ? got.data.news : [];

  const mentions = (haystack) => {
    const hay = String(haystack || '').toLowerCase();
    if (hay.indexOf(ticker.toLowerCase()) >= 0) return true;
    return key.length >= 3 && hay.indexOf(key.toLowerCase()) >= 0;
  };

  // Feed order is not relevance order. A market wrap that name-drops the company
  // once in its summary sits above the story about that company's new CEO, and
  // whichever one comes first is the line that ends up in the brief. So a
  // headline that names the company in its own title outranks one that only
  // mentions it further down.
  const relevant = news
    .map((n, order) => ({ n, order, inTitle: mentions(n.title) }))
    .filter((r) => r.inTitle || mentions(r.n.summary))
    .sort((a, b) => (b.inTitle ? 1 : 0) - (a.inTitle ? 1 : 0) || a.order - b.order)
    .map((r) => r.n);

  return {
    json: {
      ticker,
      headlines: relevant.slice(0, 3).map((n) => ({
        title: String(n.title || '').slice(0, 160),
        provider: String(n.provider || '').slice(0, 40),
        when: String(n.pubDate || '').slice(0, 10),
      })),
      returned: news.length,
      kept: relevant.length,
      news_note: got.error || got.note || null,
    },
  };
});

