// One message for the whole watchlist, not one per ticker. The IF above has
// already narrowed this branch to the movers, so the full picture is read back
// from the compare node by name.
const cfg = $('Settings').first().json;
const rows = $('Compare With Last Time').all().map((i) => i.json).filter((r) => r.usable);
const movers = rows.filter((r) => r.moved);
const news = {};
for (const item of $('Read The Headlines').all()) news[item.json.ticker] = item.json;

// The chain is set to continue on error, so a model that failed leaves an item
// with no text rather than no item at all. The numbers are the message; the
// paragraph is a nicety.
const commentary = String(($json && $json.text) || '').trim();

const money = (v) => (v === null || v === undefined ? 'n/a' : '$' + Number(v).toFixed(2));
const pct = (v) => (v === null || v === undefined ? 'n/a' : (v > 0 ? '+' : '') + Number(v).toFixed(1) + '%');

const LABEL = {
  strong_buy: 'Strong Buy', buy: 'Buy', hold: 'Hold',
  sell: 'Sell', strong_sell: 'Strong Sell', unknown: 'unrated',
};

const lines = ['*Analyst drift* - ' + movers.length + ' of ' + rows.length + ' moved', ''];

for (const r of movers) {
  lines.push('*' + r.ticker + '*' + (r.long_name ? ' ' + r.long_name : '') + '  ' + money(r.price) +
    (r.change_pct === null || r.change_pct === undefined ? '' : ' (' + pct(r.change_pct) + ' today)'));

  // Only spell out a move that happened. A ticker caught by a rating change
  // reads "target $571.38 to $571.38 (0.0%)" otherwise - a line saying nothing,
  // in a digest whose whole job is to carry only what changed.
  if (r.target_move_pct !== null && Math.abs(r.target_move_pct) >= 0.1) {
    lines.push('  target ' + money(r.prev_target) + ' to ' + money(r.mean_target) + ' (' + pct(r.target_move_pct) + ')');
  } else if (r.mean_target !== null) {
    lines.push('  target ' + money(r.mean_target) + (r.upside_pct === null ? '' : ', ' + pct(r.upside_pct) + ' from here'));
  }

  if (r.rating_changed) {
    lines.push('  rating ' + (LABEL[r.prev_consensus] || r.prev_consensus) + ' to ' + (LABEL[r.consensus] || r.consensus) +
      (r.analyst_count === null ? '' : ' on ' + r.analyst_count + ' analysts'));
  }

  if (r.eps_move_pct !== null && Math.abs(r.eps_move_pct) >= 0.1) {
    lines.push('  next year EPS ' + pct(r.eps_move_pct) + ' to ' + money(r.eps_next_year));
  }

  // The distribution shifts slowly and monthly, so it is context rather than a
  // reason to send anything. Three points is roughly one analyst in thirty.
  if (r.bull_share !== null && r.bull_share_prev !== null &&
      Math.abs(r.bull_share - r.bull_share_prev) >= 3) {
    lines.push('  buy-side share ' + r.bull_share_prev.toFixed(0) + '% to ' + r.bull_share.toFixed(0) + '% over a month');
  }

  for (const a of (r.firm_actions || []).slice(0, 4)) {
    const what = a.initiation
      ? 'started coverage at ' + (a.to_grade || 'no grade') + (a.new_target === null ? '' : ', target ' + money(a.new_target))
      : a.graded
        ? a.from_grade + ' to ' + a.to_grade + (a.target_change_pct === null ? '' : ', target ' + pct(a.target_change_pct))
        : 'target ' + money(a.prior_target) + ' to ' + money(a.new_target) + ' (' + pct(a.target_change_pct) + ')';
    lines.push('  - ' + a.when + ' ' + a.firm + ': ' + what);
  }

  const h = news[r.ticker];
  if (h && h.headlines && h.headlines.length) {
    lines.push('  _' + h.headlines[0].title + '_ - ' + h.headlines[0].provider);
  } else if (h && h.returned) {
    // Saying nothing here would read as "no news"; the honest version is that
    // there was news and none of it was about this company.
    lines.push('  _' + h.returned + ' stories in the feed, none about this company._');
  }
  lines.push('');
}

if (commentary) lines.push(commentary, '');

const first = rows.filter((r) => r.first_run).map((r) => r.ticker);
if (first.length) {
  lines.push('_First reading for ' + first.join(', ') + ' - recorded, nothing to compare against yet._');
}

const noEps = rows.filter((r) => r.eps_note).map((r) => r.ticker);
if (noEps.length) {
  lines.push('_No EPS estimate for ' + noEps.join(', ') + ' - that signal is missing, the rest still stands._');
}

const missing = (rows[0] && rows[0].not_found) || [];
if (missing.length) lines.push('_Not on Yahoo Finance: ' + missing.join(', ') + '._');

const failed = (rows[0] && rows[0].failed) || [];
if (failed.length) lines.push('_The server could not answer for: ' + failed.join('; ') + '._');

const window = movers.length ? movers[0].action_window_days : 7;
lines.push('_Firm actions cover the last ' + window + ' days of the ten Yahoo returns per ticker._');

// Telegram rejects anything over 4096 characters with a 400, which arrives as a
// failed node after every number in the message was already right.
let message = lines.join('\n');
if (message.length > 3900) message = message.slice(0, 3900) + '\n\n_...trimmed._';

return [{ json: { message, chat_id: cfg.telegram_chat_id, moved: movers.length } }];
